async function refresh(){if(EVM_CHAINS[network()])return refreshEvm();if(!owner)return notice('Connect your wallet first.');const snapshot=epoch,address=owner,connection=conn();$('state').textContent='loading';try{await verifyNetwork(connection,network());const [balance,...tokens]=await Promise.all([connection.getBalance(address),connection.getParsedTokenAccountsByOwner(address,{programId:TOKEN_PROGRAM_ID}),connection.getParsedTokenAccountsByOwner(address,{programId:TOKEN_2022_PROGRAM_ID})]);if(snapshot!==epoch)return;assets=[{id:'SOL',native:true,name:'Solana',mint:'',raw:BigInt(balance),decimals:9,display:String(balance/1e9)},...tokens.flatMap((result,i)=>result.value.map(t=>{const info=t.account.data.parsed.info;return{id:t.pubkey.toBase58(),name:'Token · '+info.mint.slice(0,4),mint:info.mint,raw:BigInt(info.tokenAmount.amount),decimals:info.tokenAmount.decimals,display:info.tokenAmount.uiAmountString,source:t.pubkey,program:i===0?TOKEN_PROGRAM_ID:TOKEN_2022_PROGRAM_ID}}).filter(t=>t.raw>0n))];$('balance').textContent=String(balance/1e9);$('state').textContent='connected';render();await history(connection,address,snapshot)}catch(e){if(snapshot!==epoch)return;$('state').textContent='RPC unavailable';error(new Error('Unable to load blockchain data: '+e.message+'. Try another RPC in Settings.'))}}
