function units(value,decimals){if(!/^\d+(\.\d+)?$/.test(value))throw Error('Enter a positive decimal amount.');const [whole,fraction='']=value.split('.');if(fraction.length>decimals)throw Error('Too many decimal places.');const raw=BigInt(whole)*10n**BigInt(decimals)+BigInt(fraction.padEnd(decimals,'0')||'0');if(raw<=0n)throw Error('Amount must be greater than zero.');return raw}
function send(id='SOL'){if(EVM_CHAINS[network()])return sendEvm(id);if(!owner)return walletChoice();if(!assets.length)return notice('Refresh balances before sending.');modal(`<div class="eyebrow">TRANSFER / ${network()==='devnet'?'DEVNET':'MAINNET — REAL ASSETS'}</div><h2>Send assets</h2><label for="assetSelect">Asset</label><select id="assetSelect">${assets.filter(a=>a.native||a.program.equals(TOKEN_PROGRAM_ID)).map(a=>`<option value="${a.id}" ${a.id===id?'selected':''}>${esc(a.name)} · ${esc(a.display)}</option>`).join('')}</select><label for="recipient">Recipient’s Solana address</label><input id="recipient" autocomplete="off" placeholder="Enter public wallet address"><label for="amount">Amount</label><input id="amount" inputmode="decimal" placeholder="0.00"><p class="muted">SOL pays network fees. Standard SPL tokens are supported for sending; Token-2022 assets are view-only.</p><button id="review" class="dark">Review transfer →</button>`);$('review').onclick=async()=>{try{const a=assets.find(a=>a.id===$('assetSelect').value);const recipient=new PublicKey($('recipient').value.trim()),raw=units($('amount').value.trim(),a.decimals);if(recipient.equals(owner))throw Error('Choose a recipient other than your own address.');if(raw>a.raw)throw Error('Amount exceeds the available balance.');const walletCharge=walletFee(raw),collectorText=feeRecipient(network()),collector=collectorText?new PublicKey(collectorText):null;if(collector&&raw+walletCharge>a.raw)throw Error('Insufficient asset balance including the 0.3% wallet fee.');const amount=$('amount').value.trim(),sender=owner.toBase58(),net=network(),endpoint=rpc(),snapshot=epoch;const connection=conn();$('review').disabled=true;await verifyNetwork(connection,net);const tx=new Transaction();if(a.native){tx.add(SystemProgram.transfer({fromPubkey:owner,toPubkey:recipient,lamports:raw}))}else{const destination=await getAssociatedTokenAddress(new PublicKey(a.mint),recipient);tx.add(createAssociatedTokenAccountIdempotentInstruction(owner,destination,recipient,new PublicKey(a.mint)));tx.add(createTransferCheckedInstruction(a.source,new PublicKey(a.mint),destination,owner,raw,a.decimals))}if(collector){if(a.native){tx.add(SystemProgram.transfer({fromPubkey:owner,toPubkey:collector,lamports:walletCharge}))}else{const feeDestination=await getAssociatedTokenAddress(new PublicKey(a.mint),collector);tx.add(createAssociatedTokenAccountIdempotentInstruction(owner,feeDestination,collector,new PublicKey(a.mint)));tx.add(createTransferCheckedInstruction(a.source,new PublicKey(a.mint),feeDestination,owner,walletCharge,a.decimals))}}const block=await connection.getLatestBlockhash();tx.recentBlockhash=block.blockhash;tx.feePayer=owner;const fee=await connection.getFeeForMessage(tx.compileMessage());if(fee.value==null)throw Error('Unable to estimate network fee.');const solBalance=await connection.getBalance(owner);let rent=0;if(!a.native){const addresses=[...new Map(tx.instructions.filter(i=>i.programId.toBase58()==='ATokenGPvbdGVxr1b2hvZbsiqW5xWH25efTNsLJA8knL').map(i=>[i.keys[1].pubkey.toBase58(),i.keys[1].pubkey])).values()];for(const address of addresses)if(!await connection.getAccountInfo(address))rent+=await connection.getMinimumBalanceForRentExemption(165);}if(BigInt(solBalance)<BigInt(fee.value+rent)+(a.native?raw+(collector?walletCharge:0n):0n))throw Error('Insufficient SOL for this transfer and network fees.');if(snapshot!==epoch)throw Error('Wallet or network changed. Start again.');$('modalContent').innerHTML=`<h2>Review your transfer</h2><div class="review"><p>Network: <strong>${net==='devnet'?'Solana Devnet':'Solana Mainnet — real assets'}</strong></p><p>Asset: <strong>${esc(a.name)}</strong>${a.native?'':'<br>Mint: '+esc(a.mint)}</p><p>Amount: <strong>${esc(amount)}</strong></p><p>To: <strong>${recipient.toBase58()}</strong></p><p>Wallet fee: ${collector?formatAmount(walletCharge,a.decimals):'Not activated'} ${collector?esc(a.name):'— collection wallet not configured'}</p>${collector?'<p>Fee recipient: '+collector.toBase58()+'</p>':''}<p>Network fee: ${fee.value/1e9} SOL${rent?'<br>Recipient token account: '+rent/1e9+' SOL':''}</p></div><p>${localWallet?'Sign with your unlocked wallet.':'Approve the exact details in Phantom.'} Transfers confirmed on-chain cannot be reversed.</p><button id="approve" class="dark">${localWallet?'Sign and send transfer':'Approve in Phantom ↗'}</button>`;$('approve').onclick=async()=>{if(busy)return;busy=true;$('approve').disabled=true;try{if(snapshot!==epoch||owner?.toBase58()!==sender||network()!==net||rpc()!==endpoint)throw Error('Wallet or network changed. Start again.');if(await connection.getBlockHeight()>block.lastValidBlockHeight)throw Error('Transfer expired. Please prepare it again.');await verifyNetwork(connection,net);if(snapshot!==epoch)throw Error('Wallet changed before signing.');const signed=localWallet?signSolana(core,localWallet,tx):await provider.signTransaction(tx);if(snapshot!==epoch||network()!==net||rpc()!==endpoint)throw Error('Network changed during approval. Transfer was not submitted.');const result={signature:await connection.sendRawTransaction(signed.serialize(),{skipPreflight:false})};$('modalContent').innerHTML=`<h2>Transfer submitted</h2><p>Your transaction has been broadcast. Check its confirmation on the explorer.</p><a href="${explorer('tx',result.signature)}" target="_blank" rel="noopener">Track transaction ↗</a>`;const confirmation=await connection.confirmTransaction({signature:result.signature,...block},'confirmed');if(confirmation.value.err)throw Error('Transaction failed on-chain. Check the explorer for details.');if(snapshot===epoch&&$('modal').open&&$('modalContent').querySelector('h2'))$('modalContent').querySelector('h2').textContent='Transfer confirmed';if(snapshot===epoch)await refresh()}catch(e){error(e);if($('approve'))$('approve').disabled=false}finally{busy=false}}}catch(e){error(e);if($('review'))$('review').disabled=false}}}
