function lockWallet(){localWallet?.delete();localWallet=null;clearTimeout(lockTimer);reset();$('lockWallet').classList.add('hidden');$('walletRole').textContent=walletRole==='admin'?'Admin wallet locked':'Personal wallet locked';$('modalContent').textContent='';if($('modal').open)$('modal').close();notice('Wallet locked.');}
