async function activate(wallet){if(provider?.isConnected)await provider.disconnect();localWallet=wallet;owner=new PublicKey(wallet.getAddressForCoin(core.CoinType.solana));epoch++;$('connect').textContent=owner.toBase58().slice(0,4)+'…'+owner.toBase58().slice(-4);$('account').textContent=owner.toBase58();$('state').textContent='unlocked';updateChainView();$('walletRole').textContent=walletRole==='admin'?'Admin collection wallet · local self-custody':'Personal wallet · local self-custody';$('lockWallet').classList.remove('hidden');touch();$('modal').close();await refresh()}
function walletChoice(){const hasVault=!!localStorage.getItem(VAULT_KEY);modal(`<div class="eyebrow">SELF-CUSTODY</div><h2>Your wallet. Your keys.</h2><p>Create a wallet on this device or restore from your recovery phrase. Your keys and signatures stay local.</p><div class="wallet-options">${hasVault?'<button id="unlockLocal" class="dark">Unlock wallet</button>':'<button id="createLocal" class="dark">Create wallet</button><button id="importLocal">Restore wallet</button>'}</div><p class="muted">Experimental software wallet, not independently audited. Use Solana Devnet or BNB Testnet before entrusting real assets. The password-protected vault stays in this browser.</p>`);if($('createLocal'))$('createLocal').onclick=()=>setupWallet(false);if($('importLocal'))$('importLocal').onclick=()=>setupWallet(true);if($('unlockLocal'))$('unlockLocal').onclick=unlockDialog;}
function setupWallet(importing){modal(`<div class="eyebrow">${importing?'RESTORE':'CREATE'} / LOCAL WALLET</div><h2>${importing?'Restore your wallet':'Protect your wallet'}</h2>${importing?'<label for="phrase">Recovery phrase (12, 15, 18, 21 or 24 words)</label><textarea id="phrase" rows="4" autocomplete="off" autocapitalize="off" spellcheck="false"></textarea><label for="bipPass">BIP39 passphrase (optional)</label><input id="bipPass" type="password" autocomplete="off"><p class="muted">Only enter a phrase for a wallet you own. Recovery uses Trust Wallet’s default Solana account; other derivation paths may show a different address. A BIP39 passphrase changes the derived wallet; it is separate from the vault password.</p>':''}<label for="vaultPassword">Vault password · at least 12 characters</label><input id="vaultPassword" type="password" autocomplete="new-password"><label for="passwordAgain">Confirm password</label><input id="passwordAgain" type="password" autocomplete="new-password"><p class="muted">Save your recovery phrase offline. This password only unlocks this browser; it cannot recover lost assets. Clearing browser storage deletes the local vault.</p><button id="setupContinue" class="dark">${importing?'Validate and restore':'Create recovery phrase'}</button>`);$('setupContinue').onclick=async()=>{let wallet;try{if(localStorage.getItem(VAULT_KEY))throw Error('A wallet already exists on this browser. Unlock it first.');let password=$('vaultPassword').value;if(password.length<12)throw Error('Use at least 12 characters for your password.');if(password!==$('passwordAgain').value)throw Error('Passwords do not match.');const phrase=importing?$('phrase').value:'';let passphrase=importing?$('bipPass').value:'';$('setupContinue').disabled=true;const c=await loadCore();wallet=importing?walletFromPhrase(c,phrase,passphrase):createWallet(c);const mnemonic=wallet.mnemonic();const payload={mnemonic,passphrase};const encrypted=await encryptVault(payload,password);password='';passphrase='';payload.mnemonic='';payload.passphrase='';if(!$('modal').open)throw Error('Wallet setup cancelled.');if(importing){localStorage.setItem(VAULT_KEY,JSON.stringify(encrypted));await activate(wallet);wallet=null;notice('Wallet restored. Solana uses Trust Wallet’s default derivation path.');return}const words=mnemonic.split(' ');const candidate=wallet;wallet=null;let finalized=false;function cleanup(){if(!finalized)candidate.delete();$('modalContent').textContent='';$('modal').removeEventListener('close',cleanup)}$('modal').addEventListener('close',cleanup,{once:true});$('modalContent').innerHTML=`<div class="eyebrow">PRIVATE / RECOVERY BACKUP</div><h2>Write these words down.</h2><p>Anyone with this phrase can control your funds. Keep it offline and never share it. This phrase cannot be reset.</p><div class="phrase-grid">${words.map((word,i)=>`<span><small>${i+1}</small> ${esc(word)}</span>`).join('')}</div><label for="backupWord">Verify word 3</label><input id="backupWord" autocomplete="off" spellcheck="false"><label for="backupWord2">Verify word 17</label><input id="backupWord2" autocomplete="off" spellcheck="false"><label class="check"><input id="savedBackup" type="checkbox"> I saved the complete phrase offline.</label><button id="finishWallet" class="dark">Save encrypted wallet</button>`;$('finishWallet').onclick=async()=>{try{if(!$('savedBackup').checked||$('backupWord').value.trim().toLowerCase()!==words[2]||$('backupWord2').value.trim().toLowerCase()!==words[16])throw Error('Confirm both backup words and save the complete phrase.');if(localStorage.getItem(VAULT_KEY))throw Error('Another wallet was created. Reload and unlock it.');localStorage.setItem(VAULT_KEY,JSON.stringify(encrypted));finalized=true;$('modal').removeEventListener('close',cleanup);words.fill('');$('modalContent').textContent='';await activate(candidate)}catch(e){error(e)}}}catch(e){wallet?.delete();error(e);if($('setupContinue'))$('setupContinue').disabled=false}}}
function unlockDialog(){modal('<h2>Unlock wallet</h2><label for="unlockPassword">Vault password</label><input id="unlockPassword" type="password" autocomplete="current-password"><button id="unlockNow" class="dark">Unlock wallet</button><p class="muted">The recovery phrase is decrypted on your device. It is never sent to a server.</p>');$('unlockNow').onclick=async()=>{let wallet,payload;try{$('unlockNow').disabled=true;const saved=localStorage.getItem(VAULT_KEY);if(!saved)throw Error('No local wallet found.');payload=await decryptVault(JSON.parse(saved),$('unlockPassword').value);$('unlockPassword').value='';const c=await loadCore();wallet=walletFromPhrase(c,payload.mnemonic,payload.passphrase);if(!$('modal').open)throw Error('Unlock cancelled.');payload.mnemonic='';payload.passphrase='';await activate(wallet);wallet=null}catch(e){wallet?.delete();error(e);if($('unlockNow'))$('unlockNow').disabled=false}finally{if(payload){payload.mnemonic='';payload.passphrase=''}}}}
$('manageLocal').onclick=()=>owner&&localWallet?localManagement():walletChoice();
function localManagement(){modal('<h2>Local wallet</h2><p>Your recovery phrase is protected in the browser vault. Export an encrypted backup or lock your wallet.</p><button id="exportVault" class="dark">Download encrypted backup</button><button id="revealPhrase">View recovery phrase</button><p class="muted">The encrypted backup requires your vault password. Store your recovery phrase offline as the primary backup.</p>');$('exportVault').onclick=()=>{const blob=new Blob([localStorage.getItem(VAULT_KEY)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='tiger-wallet-encrypted-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('revealPhrase').onclick=()=>{modal('<h2>Verify before revealing</h2><label for="revealPassword">Vault password</label><input id="revealPassword" type="password" autocomplete="current-password"><button id="revealNow" class="dark">Reveal recovery phrase</button>');$('revealNow').onclick=async()=>{let payload;try{payload=await decryptVault(JSON.parse(localStorage.getItem(VAULT_KEY)),$('revealPassword').value);$('modalContent').innerHTML='<h2>Keep this private</h2><p>Anyone with this phrase controls your funds. Never share it.</p><div class="address"></div>';$('modalContent').querySelector('.address').textContent=payload.mnemonic;setTimeout(()=>{if($('modal').open){$('modalContent').textContent='';$('modal').close()}},30000)}catch(e){error(e)}finally{if(payload){payload.mnemonic='';payload.passphrase=''}}}}}
$('restoreBackup').onclick=()=>{if(localStorage.getItem(VAULT_KEY))return notice('A local wallet already exists. Use it or restore in a separate browser profile.');modal('<h2>Restore encrypted backup</h2><label for="backupFile">Encrypted vault JSON</label><input id="backupFile" type="file" accept="application/json,.json"><label for="backupPassword">Original vault password</label><input id="backupPassword" type="password"><button id="restoreFile" class="dark">Validate and restore</button>');$('restoreFile').onclick=async()=>{let wallet,payload;try{const file=$('backupFile').files[0];if(!file||file.size>65536)throw Error('Choose a valid encrypted vault file under 64 KB.');const saved=JSON.parse(await file.text());payload=await decryptVault(saved,$('backupPassword').value);const c=await loadCore();wallet=walletFromPhrase(c,payload.mnemonic,payload.passphrase);if(localStorage.getItem(VAULT_KEY))throw Error('A local wallet already exists.');localStorage.setItem(VAULT_KEY,JSON.stringify(saved));await activate(wallet);wallet=null}catch(e){wallet?.delete();error(e)}finally{if(payload){payload.mnemonic='';payload.passphrase=''}}}};
$('modal').addEventListener('close',()=>{$('modalContent').textContent=''});
const evmAddress=()=>localWallet?localWallet.getAddressForCoin(core.CoinType.ethereum):null;const chain=()=>EVM_CHAINS[network()];const tokenKey=()=>`tiger-tokens-${network()}`;const activityKey=address=>`tiger-activity-${network()}-${address.toLowerCase()}`;const tokenContracts=()=>{try{const value=JSON.parse(localStorage.getItem(tokenKey())||'[]');return Array.isArray(value)?value.filter(a=>/^0x[0-9a-fA-F]{40}$/.test(a)).slice(0,100):[]}catch{return []}};
function updateChainView(){const c=chain();$('balanceLabel').textContent=`AVAILABLE ${c?.symbol||'SOL'} BALANCE`;$('nativeSymbol').textContent=c?.symbol||'SOL';$('addToken').classList.toggle('hidden',!c);if(localWallet){const address=c?evmAddress():localWallet.getAddressForCoin(core.CoinType.solana);$('account').textContent=address;$('connect').textContent=address.slice(0,5)+'…'+address.slice(-4)}$('search').placeholder=c?'Search assets or contract address':'Search assets or mint address'}
function renderEvm(){const address=evmAddress();$('count').textContent=address?assets.length:0;$('assets').className=address?'':'empty';if(!address){$('assets').innerHTML='<div class="empty-icon">◇</div><h3>One wallet. More networks.</h3><p>Create or unlock your wallet to view native assets and ERC20 tokens.</p><button id="openEvm" class="connect-link">Open wallet ↗</button>';$('openEvm').onclick=walletChoice;return}const filter=$('search').value.toLowerCase();const selected=assets.filter(a=>(a.name+a.mint).toLowerCase().includes(filter));$('assets').innerHTML=selected.length?selected.map(a=>`<div class="asset-row"><div class="asset-name"><span class="coin">${a.native?'◆':'◇'}</span><div><strong>${esc(a.name)}</strong><small>${a.native?esc(chain().name):esc(a.mint.slice(0,8)+'…'+a.mint.slice(-6))}</small></div></div><span class="network-tag">${chain().name}</span><strong>${esc(a.display)}</strong><button data-evm-send="${esc(a.id)}">Send</button></div>`).join(''):'<div class="empty">No matching assets. Add an ERC20 / BEP20 token by contract address.</div>';document.querySelectorAll('[data-evm-send]').forEach(b=>b.onclick=()=>sendEvm(b.dataset.evmSend))}
async function refreshEvm(){const address=evmAddress();if(!address)return notice('Unlock your wallet to use the selected EVM network.');const c=chain(),endpoint=rpc(),call=evmRpc(endpoint),snapshot=epoch;$('state').textContent='loading';try{await verifyEvm(call,c);const raw=BigInt(await call('eth_getBalance',[address,'latest']));const imported=await Promise.allSettled(tokenContracts().map(contract=>tokenInfo(call,contract,address)));if(snapshot!==epoch)return;assets=[{id:'native',native:true,name:c.symbol,mint:'',raw,decimals:18,display:formatAmount(raw,18)},...imported.filter(t=>t.status==='fulfilled').map(t=>t.value)];$('balance').textContent=formatAmount(raw,18);$('state').textContent='unlocked';renderEvm();renderEvmHistory(address,c);const failed=imported.filter(t=>t.status==='rejected').length;if(failed)notice(`${failed} imported token balance(s) could not be loaded.`)}catch(e){if(snapshot!==epoch)return;$('state').textContent='RPC unavailable';error(e)}}
function renderEvmHistory(address,c){let records=[];try{records=JSON.parse(localStorage.getItem(activityKey(address))||'[]')}catch{}$('history').className='table';$('history').innerHTML='<div class="empty"><p>Transfers submitted from this browser. For complete on-chain activity, <a target="_blank" rel="noopener" href="'+c.explorer+'/address/'+address+'">open the explorer ↗</a>.</p></div>'+records.slice(0,30).map(r=>`<div class="tx-row"><div><a href="${c.explorer}/tx/${esc(r.hash)}" target="_blank" rel="noopener">${esc(r.hash.slice(0,14))}… ↗</a><br><small>${esc(new Date(r.time).toLocaleString())}</small></div><span>${esc(r.status||'Submitted')} · ${esc(r.amount)} ${esc(r.symbol)}</span></div>`).join('')}
function receiveEvm(){const address=evmAddress(),c=chain();if(!address)return walletChoice();modal(`<div class="eyebrow">RECEIVE / ${esc(c.name)}</div><h2>Your receiving address</h2><p>Send ${esc(c.symbol)} or ERC20 / BEP20 tokens using ${esc(c.name)} only. The same address can exist on other EVM networks; selecting this network does not bridge assets.</p><div class="address">${address}</div><button id="copyEvm" class="dark">Copy address</button><p><a href="${c.explorer}/address/${address}" target="_blank" rel="noopener">View on explorer ↗</a></p>`);$('copyEvm').onclick=async()=>{try{await navigator.clipboard.writeText(address);$('copyEvm').textContent='Address copied'}catch(e){error(e)}}}
$('addToken').onclick=()=>{if(!evmAddress())return walletChoice();modal(`<h2>Add ERC20 / BEP20 token</h2><p>Enter the token contract on ${esc(chain().name)}. Token names are not proof of authenticity; verify the address before transacting.</p><label for="tokenContract">Contract address</label><input id="tokenContract" placeholder="0x…" autocomplete="off"><button id="importToken" class="dark">Read token from blockchain</button>`);$('importToken').onclick=async()=>{try{const contract=$('tokenContract').value.trim(),snapshot=epoch;if(!core.AnyAddress.isValid(contract,core.CoinType.ethereum)||/^0x0{40}$/i.test(contract))throw Error('Enter a valid nonzero EVM contract address.');$('importToken').disabled=true;const call=evmRpc(rpc());await verifyEvm(call,chain());if(await call('eth_getCode',[contract,'latest'])==='0x')throw Error('No contract exists at this address on the selected network.');const token=await tokenInfo(call,contract,evmAddress());if(snapshot!==epoch||!$('modal').open)throw Error('Network changed or import cancelled.');const contracts=tokenContracts();if(!contracts.some(t=>t.toLowerCase()===contract.toLowerCase()))contracts.push(contract);if(contracts.length>100)throw Error('Token limit reached.');localStorage.setItem(tokenKey(),JSON.stringify(contracts));$('modal').close();await refreshEvm();notice(token.name+' added.')}catch(e){error(e);if($('importToken'))$('importToken').disabled=false}}};
function sendEvm(id='native'){const address=evmAddress();if(!address)return walletChoice();if(!assets.length)return notice('Refresh your balance first.');const c=chain();modal(`<div class="eyebrow">TRANSFER / ${esc(c.name)}</div><h2>Send assets</h2><label for="evmAsset">Asset</label><select id="evmAsset">${assets.map(a=>`<option value="${esc(a.id)}" ${a.id===id?'selected':''}>${esc(a.name)} · ${esc(a.display)}</option>`).join('')}</select><label for="evmRecipient">Recipient address</label><input id="evmRecipient" autocomplete="off" placeholder="0x…"><label for="evmAmount">Amount</label><input id="evmAmount" inputmode="decimal" placeholder="0.00"><p class="muted">${esc(c.symbol)} pays network fees. Transfers remain on ${esc(c.name)}.</p><button id="evmReview" class="dark">Review transfer →</button>`);$('evmReview').onclick=async()=>{try{const asset=assets.find(a=>a.id===$('evmAsset').value),recipient=$('evmRecipient').value.trim(),amount=$('evmAmount').value.trim(),raw=parseAmount(amount,asset.decimals),snapshot=epoch,net=network(),endpoint=rpc();if(!core.AnyAddress.isValid(recipient,core.CoinType.ethereum)||/^0x0{40}$/i.test(recipient))throw Error('Enter a valid nonzero recipient address.');if(recipient.toLowerCase()===address.toLowerCase())throw Error('Choose another recipient.');if(raw>asset.raw)throw Error('Amount exceeds the available balance.');$('evmReview').disabled=true;const call=evmRpc(endpoint);await verifyEvm(call,c);const collector=feeRecipient(net),walletCharge=collector?walletFee(raw):0n,router=collector?feeConfig.routers[net]:null;if(collector&&!router)throw Error('Fee collection is configured, but this network needs its deployed fee router.');if(raw+walletCharge>asset.raw)throw Error('Insufficient asset balance including wallet fee.');if(router){if(!core.AnyAddress.isValid(router,core.CoinType.ethereum)||await call('eth_getCode',[router,'latest'])==='0x')throw Error('Invalid fee router.');const expected=await call('eth_call',[{to:router,data:routerGetter('collector()')},'latest']);const rate=await call('eth_call',[{to:router,data:routerGetter('basisPoints()')},'latest']);if(expected.slice(-40).toLowerCase()!==collector.slice(2).toLowerCase()||BigInt(rate)!==30n)throw Error('Router collector or fee rate mismatch.');if(!asset.native){const allowance=BigInt(await call('eth_call',[{to:asset.mint,data:allowanceData(address,router)},'latest']));if(allowance<raw+walletCharge){showTokenApproval(call,c,asset,router,raw+walletCharge,address,snapshot,net,endpoint);return;}}}const destination=router||(asset.native?recipient:asset.mint),data=router?routerData(asset.native?null:asset.mint,recipient,raw):(asset.native?'0x':tokenTransferData(recipient,raw)),value=asset.native?raw+walletCharge:0n;const [nonceHex,gasPriceHex,estimateHex,balanceHex]=await Promise.all([call('eth_getTransactionCount',[address,'pending']),call('eth_gasPrice'),call('eth_estimateGas',[{from:address,to:destination,value:hex(value),data}]),call('eth_getBalance',[address,'latest'])]);const gasPrice=BigInt(gasPriceHex),gasLimit=(BigInt(estimateHex)*120n+99n)/100n,fee=gasPrice*gasLimit;if(fee+value>BigInt(balanceHex))throw Error('Insufficient '+c.symbol+' for amount and maximum network fee.');if(snapshot!==epoch||!$('modal').open)throw Error('Wallet changed or review cancelled.');const request={chainId:c.chainId,nonce:BigInt(nonceHex),gasPrice,gasLimit,to:destination,value,data};const preparedAt=Date.now();$('modalContent').innerHTML=`<h2>Review transfer</h2><div class="review"><p>Network: <strong>${esc(c.name)}${c.test?' · test assets':' · real assets'}</strong></p><p>Amount: <strong>${esc(amount)} ${esc(asset.name)}</strong></p>${asset.native?'':'<p>Contract: '+esc(asset.mint)+'</p>'}<p>To: <strong>${esc(recipient)}</strong></p><p>Wallet fee (0.3%): ${collector?formatAmount(walletCharge,asset.decimals)+' '+esc(asset.name):'Not activated — collection wallet not configured'}</p>${collector?'<p>Fee collector: '+esc(collector)+'</p><p>Atomic router: '+esc(router)+'</p>':''}<p>Maximum network fee: ${formatAmount(fee,18)} ${esc(c.symbol)}</p></div><p>Sign locally with your unlocked wallet. Confirm the network and recipient; confirmed transfers cannot be reversed.</p><button id="evmApprove" class="dark">Sign and send</button>`;$('evmApprove').onclick=async()=>{if(busy)return;busy=true;$('evmApprove').disabled=true;try{if(snapshot!==epoch||network()!==net||rpc()!==endpoint||!localWallet||evmAddress()!==address)throw Error('Wallet or network changed. Prepare the transfer again.');if(Date.now()-preparedAt>120000)throw Error('Fee quote expired. Prepare the transfer again.');await verifyEvm(call,c);if(BigInt(await call('eth_getTransactionCount',[address,'pending']))!==request.nonce)throw Error('Account nonce changed. Prepare the transfer again.');if(BigInt(await call('eth_getBalance',[address,'latest']))<fee+value)throw Error('Balance changed. Prepare the transfer again.');if(snapshot!==epoch||!localWallet)throw Error('Wallet locked before signing.');const encoded=signEvm(core,localWallet,request);const hash=await call('eth_sendRawTransaction',[encoded]);if(!/^0x[0-9a-fA-F]{64}$/.test(hash))throw Error('RPC returned an invalid transaction hash.');const key=`tiger-activity-${net}-${address.toLowerCase()}`;let records=[];try{records=JSON.parse(localStorage.getItem(key)||'[]')}catch{}try{localStorage.setItem(key,JSON.stringify([{hash,amount,symbol:asset.name,time:Date.now(),status:'Submitted'},...records].slice(0,50)))}catch{}if(snapshot===epoch&&$('modal').open)$('modalContent').innerHTML=`<h2>Transfer submitted</h2><p>The signed transaction was broadcast. Its receipt and confirmation are available on the explorer.</p><a href="${c.explorer}/tx/${hash}" target="_blank" rel="noopener">Track transaction ↗</a>`;if(snapshot===epoch)await refreshEvm();watchEvmReceipt(call,hash,address,net,c,snapshot)}catch(e){error(e);if($('evmApprove'))$('evmApprove').disabled=false}finally{busy=false}}}catch(e){error(e);if($('evmReview'))$('evmReview').disabled=false}}}
updateChainView();
async function watchEvmReceipt(call,hash,address,net,c,snapshot){for(let attempt=0;attempt<20;attempt++){if(snapshot!==epoch)return;try{const receipt=await call('eth_getTransactionReceipt',[hash]);if(receipt){const status=BigInt(receipt.status)===1n?'Confirmed':'Failed';const key=`tiger-activity-${net}-${address.toLowerCase()}`;try{const records=JSON.parse(localStorage.getItem(key)||'[]');records.forEach(r=>{if(r.hash===hash)r.status=status});localStorage.setItem(key,JSON.stringify(records))}catch{}if(snapshot===epoch){const link=$('modalContent').querySelector('a');if($('modal').open&&link?.href===c.explorer+'/tx/'+hash){$('modalContent').querySelector('h2').textContent='Transfer '+status.toLowerCase();$('modalContent').querySelector('p').textContent=status==='Confirmed'?'The network has confirmed this transaction.':'The transaction failed on-chain. Check the explorer for its execution details; network fees may still apply.'}notice(status==='Confirmed'?'Transfer confirmed on '+c.name+'.':'Transfer failed on-chain.');await refreshEvm()}return}}catch{}await new Promise(resolve=>setTimeout(resolve,3000))}}
$('account').tabIndex=0;$('account').role='button';$('account').title='Copy receiving address';async function copyCurrentAddress(){if(!owner)return walletChoice();const address=chain()?evmAddress():owner.toBase58();if(!address)return walletChoice();try{await navigator.clipboard.writeText(address);notice('Address copied.')}catch(e){error(e)}}$('account').onclick=copyCurrentAddress;$('account').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();copyCurrentAddress()}};

function routerGetter(signature){return '0x'+Array.from(keccak_256(new TextEncoder().encode(signature)).slice(0,4),b=>b.toString(16).padStart(2,'0')).join('');}
function showTokenApproval(call,c,asset,router,total,address,snapshot,net,endpoint){
 $('modalContent').innerHTML=`<h2>Authorize exact token amount</h2><p>The fee router needs permission to transfer ${formatAmount(total,asset.decimals)} ${esc(asset.name)}, including the 0.3% fee. This approval is a separate transaction with its own network gas cost.</p><div class="address">${esc(router)}</div><button id="approveToken" class="dark">Estimate approval gas</button>`;
 $('approveToken').onclick=async()=>{try{if(snapshot!==epoch||!localWallet||network()!==net||rpc()!==endpoint)throw Error('Wallet or network changed.');const data=approvalData(router,total);const gasPrice=BigInt(await call('eth_gasPrice'));const gasLimit=(BigInt(await call('eth_estimateGas',[{from:address,to:asset.mint,value:'0x0',data}]))*120n+99n)/100n;const fee=gasPrice*gasLimit;$('modalContent').innerHTML=`<h2>Review token permission</h2><p>Token: ${esc(asset.mint)}</p><p>Spender: ${esc(router)}</p><p>Exact allowance: ${formatAmount(total,asset.decimals)} ${esc(asset.name)}</p><p>Maximum gas: ${formatAmount(fee,18)} ${esc(c.symbol)}</p><button id="signApproval" class="dark">Sign exact approval</button>`;const reviewed=Date.now();$('signApproval').onclick=async()=>{if(busy)return;busy=true;try{if(snapshot!==epoch||!localWallet||network()!==net||rpc()!==endpoint||Date.now()-reviewed>120000)throw Error('Approval expired or wallet changed.');$('signApproval').disabled=true;await verifyEvm(call,c);if(BigInt(await call('eth_getBalance',[address,'latest']))<fee)throw Error('Insufficient native gas balance.');const nonce=BigInt(await call('eth_getTransactionCount',[address,'pending']));if(snapshot!==epoch||!localWallet)throw Error('Wallet locked.');const hash=await call('eth_sendRawTransaction',[signEvm(core,localWallet,{chainId:c.chainId,nonce,gasPrice,gasLimit,to:asset.mint,value:0n,data})]);$('modalContent').innerHTML=`<h2>Approval submitted</h2><p>Wait for confirmation, then prepare your transfer again. No transfer has been sent yet.</p><a href="${c.explorer}/tx/${esc(hash)}" target="_blank" rel="noopener">Check approval ↗</a>`;}catch(e){error(e);if($('signApproval'))$('signApproval').disabled=false}finally{busy=false}};}catch(e){error(e)}};
}
$('feeStatus').textContent=feeConfig.solana||feeConfig.evm?'Fee collection configured. Each transfer displays its collector and fee before signing.':'Fee collection is not activated. Create the admin wallet, then publish its public configuration. Current transfers have no wallet fee.';
function downloadJson(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('adminSetup').onclick=()=>{modal('<h2>Admin collection wallet</h2><p>Create a separate self-custody wallet for fee revenue. This grants no access to customer wallets. Keys and the encrypted backup remain on this device.</p><label for="adminPassword">Admin vault password · at least 12 characters</label><input id="adminPassword" type="password" autocomplete="new-password"><label for="adminAgain">Confirm password</label><input id="adminAgain" type="password" autocomplete="new-password"><button id="generateAdmin" class="dark">Generate locally</button>');$('generateAdmin').onclick=async()=>{let wallet;try{if(localStorage.getItem('tiger-admin-vault-v1'))throw Error('An admin vault already exists on this device. Export it instead of overwriting it.');const password=$('adminPassword').value;if(password.length<12||password!==$('adminAgain').value)throw Error('Use matching passwords with at least 12 characters.');$('generateAdmin').disabled=true;await loadCore();wallet=createWallet(core);const words=wallet.mnemonic().split(' '),publicConfig={basisPoints:30,solana:wallet.getAddressForCoin(core.CoinType.solana),evm:wallet.getAddressForCoin(core.CoinType.ethereum),routers:{}};const encrypted=await encryptVault({mnemonic:words.join(' '),passphrase:''},password);wallet.delete();wallet=null;if(!$('modal').open){words.fill('');return;}$('modalContent').innerHTML=`<h2>Back up the admin wallet</h2><p>Write all words offline. Never send them to anyone. Only public addresses belong in the site configuration.</p><div class="phrase-grid">${words.map((w,i)=>`<span><small>${i+1}</small> ${esc(w)}</span>`).join('')}</div><label for="adminWord">Word 17</label><input id="adminWord" autocomplete="off"><label class="check"><input id="adminSaved" type="checkbox"> I saved all 24 words offline.</label><button id="saveAdmin" class="dark">Save admin vault</button>`;const clean=()=>words.fill('');$('modal').addEventListener('close',clean,{once:true});$('saveAdmin').onclick=()=>{try{if(!$('adminSaved').checked||$('adminWord').value.trim()!==words[16])throw Error('Verify the backup first.');if(localStorage.getItem('tiger-admin-vault-v1'))throw Error('Admin wallet already exists.');localStorage.setItem('tiger-admin-vault-v1',JSON.stringify(encrypted));localStorage.setItem('tiger-admin-public-v1',JSON.stringify(publicConfig));words.fill('');$('adminSetup').textContent='Manage admin collection wallet';$('adminSetup').onclick=adminExports;adminExports();}catch(e){error(e)}};}catch(e){wallet?.delete();error(e)}};};
function adminExports(){const saved=JSON.parse(localStorage.getItem('tiger-admin-public-v1'));modal(`<h2>Admin collection wallet</h2><p>Solana collection address</p><div class="address">${esc(saved.solana)}</div><p>EVM collection address</p><div class="address">${esc(saved.evm)}</div><p>Unlock this separate wallet to view balances, receive revenue and send funds. Your personal wallet remains saved.</p><button id="openAdmin" class="dark">Unlock admin wallet</button><button id="deployRouter">Deploy fee router on selected EVM chain</button><button id="downloadAdmin">Download encrypted admin backup</button><button id="downloadConfig">Download public fee configuration</button><p class="muted">Collection is not activated globally until the site owner publishes the public configuration. Router deployment uses this wallet’s native gas. Keep the recovery phrase offline.</p>`);$('openAdmin').onclick=()=>switchWallet('admin');$('deployRouter').onclick=deployAdminRouter;$('downloadAdmin').onclick=()=>downloadJson('tiger-admin-encrypted-backup.json',JSON.parse(localStorage.getItem('tiger-admin-vault-v1')));$('downloadConfig').onclick=()=>downloadJson('fee-config.json',saved);}

if(localStorage.getItem('tiger-admin-vault-v1')){$('adminSetup').textContent='Manage admin collection wallet';$('adminSetup').onclick=adminExports;}

function switchWallet(role){if(busy)return notice('Wait for the current transaction.');if(localWallet)lockWallet();walletRole=role;VAULT_KEY=role==='admin'?'tiger-admin-vault-v1':'tiger-vault-v1';$('walletRole').textContent=role==='admin'?'Admin collection wallet · locked':'Personal wallet · locked';if(!localStorage.getItem(VAULT_KEY)){if(role==='admin')return notice('Create or restore the admin wallet first.');return walletChoice();}unlockDialog();}
$('personalWallet').onclick=()=>switchWallet('personal');
$('restoreAdmin').onclick=()=>{if(localStorage.getItem('tiger-admin-vault-v1'))return adminExports();modal('<h2>Restore admin wallet</h2><label for="adminFile">Encrypted admin backup</label><input id="adminFile" type="file" accept=".json,application/json"><label for="restoreAdminPassword">Backup password</label><input id="restoreAdminPassword" type="password"><button id="importAdminNow" class="dark">Restore locally</button>');$('importAdminNow').onclick=async()=>{let candidate,payload;try{$('importAdminNow').disabled=true;const file=$('adminFile').files[0];if(!file||file.size>65536)throw Error('Choose an encrypted backup under 64 KB.');const encrypted=JSON.parse(await file.text());payload=await decryptVault(encrypted,$('restoreAdminPassword').value);await loadCore();candidate=walletFromPhrase(core,payload.mnemonic,payload.passphrase);const publicConfig={basisPoints:30,solana:candidate.getAddressForCoin(core.CoinType.solana),evm:candidate.getAddressForCoin(core.CoinType.ethereum),routers:{}};if(!$('modal').open||localStorage.getItem('tiger-admin-vault-v1'))throw Error('Restore cancelled or admin wallet already exists.');localStorage.setItem('tiger-admin-vault-v1',JSON.stringify(encrypted));localStorage.setItem('tiger-admin-public-v1',JSON.stringify(publicConfig));$('adminSetup').textContent='Manage admin collection wallet';$('adminSetup').onclick=adminExports;adminExports();}catch(e){error(e);if($('importAdminNow'))$('importAdminNow').disabled=false}finally{candidate?.delete();if(payload){payload.mnemonic='';payload.passphrase='';}}};};
async function deployAdminRouter(){try{if(walletRole!=='admin'||!localWallet)return notice('Unlock the admin wallet first, select an EVM network, then reopen admin management.');const c=chain();if(!c)throw Error('Select an EVM network before deploying.');const config=JSON.parse(localStorage.getItem('tiger-admin-public-v1'));const address=evmAddress();if(address.toLowerCase()!==config.evm.toLowerCase())throw Error('Admin wallet does not match the collection address.');if(config.routers[network()])throw Error('A router is already recorded for this chain. Export the public configuration.');const snapshot=epoch,net=network(),endpoint=rpc(),call=evmRpc(endpoint);await verifyEvm(call,c);const data='0x'+routerArtifact.evm.bytecode.object+config.evm.slice(2).padStart(64,'0');const gasPrice=BigInt(await call('eth_gasPrice')),gasLimit=(BigInt(await call('eth_estimateGas',[{from:address,data,value:'0x0'}]))*120n+99n)/100n,maximum=gasPrice*gasLimit;const prepared=Date.now();if(snapshot!==epoch||!localWallet)throw Error('Wallet changed.');modal(`<h2>Deploy fee router</h2><p>Network: ${esc(c.name)}${c.test?' · test assets':' · real assets'}</p><p>Immutable collector: ${esc(config.evm)}</p><p>Wallet fee: 0.3%. The collector cannot be changed after deployment.</p><p>Maximum gas: ${formatAmount(maximum,18)} ${esc(c.symbol)}</p><p class="muted">Experimental contract; compiled but not independently audited or tested on-chain. This deploys a real contract and pays network gas.</p><button id="confirmDeploy" class="dark">Sign router deployment</button>`);$('confirmDeploy').onclick=async()=>{if(busy)return;busy=true;$('confirmDeploy').disabled=true;try{if(snapshot!==epoch||network()!==net||rpc()!==endpoint||walletRole!=='admin'||!localWallet||Date.now()-prepared>120000)throw Error('Deployment review expired or wallet changed.');await verifyEvm(call,c);const balance=BigInt(await call('eth_getBalance',[address,'latest']));if(balance<maximum)throw Error('Fund the admin wallet with '+c.symbol+' for deployment gas.');const nonce=BigInt(await call('eth_getTransactionCount',[address,'pending']));if(snapshot!==epoch||!localWallet)throw Error('Admin wallet locked.');const raw=signEvm(core,localWallet,{chainId:c.chainId,nonce,gasPrice,gasLimit,to:'',value:0n,data});const hash=await call('eth_sendRawTransaction',[raw]);if(!/^0x[0-9a-f]{64}$/i.test(hash))throw Error('Invalid transaction hash.');localStorage.setItem('tiger-router-deployment-'+net,JSON.stringify({hash,collector:config.evm,network:net,endpoint,chainId:c.chainId}));modal(`<h2>Router deployment submitted</h2><p>Check the explorer, then use Check router deployment to recover its address after confirmation.</p><a href="${c.explorer}/tx/${hash}" target="_blank" rel="noopener">View deployment ↗</a>`);}catch(e){error(e);if($('confirmDeploy'))$('confirmDeploy').disabled=false}finally{busy=false}};}catch(e){error(e);}}
$('checkRouter').onclick=async()=>{try{const pending=JSON.parse(localStorage.getItem('tiger-router-deployment-'+network())||'null');if(!pending)throw Error('No deployment recorded for this network.');const c=chain();if(!c)throw Error('Select an EVM network.');const call=evmRpc(pending.endpoint);await verifyEvm(call,c);const receipt=await call('eth_getTransactionReceipt',[pending.hash]);if(!receipt)throw Error('Deployment is still pending.');if(BigInt(receipt.status)!==1n||!receipt.contractAddress)throw Error('Deployment failed. Check the explorer.');const collector=await call('eth_call',[{to:receipt.contractAddress,data:routerGetter('collector()')},'latest']),rate=await call('eth_call',[{to:receipt.contractAddress,data:routerGetter('basisPoints()')},'latest']);const config=JSON.parse(localStorage.getItem('tiger-admin-public-v1'));if(config.evm.toLowerCase()!==pending.collector.toLowerCase()||collector.slice(-40).toLowerCase()!==config.evm.slice(2).toLowerCase()||BigInt(rate)!==30n)throw Error('Router verification failed.');config.routers[network()]=receipt.contractAddress;localStorage.setItem('tiger-admin-public-v1',JSON.stringify(config));adminExports();notice('Router verified. Download and publish the updated public fee configuration.');}catch(e){error(e)}};
